package com.autoops.dataset.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="dataset_imports")public class DatasetImport{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String filename;@Column(name="object_key")private String objectKey;@Column(nullable=false)private String status="UPLOADED";@Column(name="total_records")private Integer totalRecords=0;@Column(name="processed_records")private Integer processedRecords=0;@Column(name="added_records")private Integer addedRecords=0;@Column(name="duplicate_records")private Integer duplicateRecords=0;@Column(name="rejected_records")private Integer rejectedRecords=0;@Column(name="failed_records")private Integer failedRecords=0;@Column(name="uploaded_by",nullable=false)private Long uploadedBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();public Long getId(){return id;}public Long getUploadedBy(){return uploadedBy;}public void setFilename(String v){filename=v;}public void setObjectKey(String v){objectKey=v;}public void setUploadedBy(Long v){uploadedBy=v;}public void setStatus(String v){status=v;}}
